async () => {
  const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
  const frameEl = () => window.containerRef?.current ?? document.querySelector("iframe");
  const win = () => frameEl()?.contentWindow;
  const api = () => win()?.ConfiguratorAPI;
  const txt = (s) => (s || "").replace(/\s+/g, " ").trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); const cs = getComputedStyle(e); return r.width > 0 && r.height > 0 && cs.visibility !== "hidden" && cs.display !== "none"; };
  const scope = async () => {
    const caps = await api().cabinets.getCapabilities();
    return { apiInstanceId: caps.data.apiInstanceId, compositionId: caps.data.activeCompositionId };
  };
  const cabinets = async () => {
    const s = await api().cabinets.getState(await scope());
    return s.data?.cabinets ?? [];
  };
  const brief = async () => (await cabinets()).map((c) => {
    const k = c.selection ?? {};
    return { id: c.id, def: c.definitionId, Width: k.Width, Drawers: k.Drawers ?? k.CabinetStyle, HandleStyle: k.HandleStyle, HandleColor: k.HandleColor, Handle: k.Handle, sinkType: k.sinkType, keys: undefined };
  });
  const button = (text) => [...document.querySelectorAll("button")].filter(vis).find((b) => txt(b.textContent) === text);
  const clickText = (text) => {
    const all = [...document.querySelectorAll("button,a,[role=button],[role=option],[role=radio],[role=tab],[role=menuitem],label,li,div,span,p")]
      .filter((e) => vis(e) && txt(e.innerText) === text);
    if (!all.length) return false;
    all.sort((a, b) => a.innerText.length - b.innerText.length);
    const el = all.at(-1).closest("button,a,[role=button],[role=option],[role=radio],[role=tab],label") || all.at(-1);
    el.click();
    return true;
  };
  const label = (text) => [...document.querySelectorAll("[class*=_label_]")].find((e) => e.textContent === text);
  const clickItem = (text) => {
    const item = label(text)?.closest("[class*=_item_]");
    if (!item) return false;
    item.click();
    return true;
  };
  const select = (id) => {
    const tool = api().getSelectTool();
    tool.deselectAll();
    tool.setSelectedByName(id, { mode: "replace" });
  };
  const deselect = async () => { api().getSelectTool().deselectAll(); await sleep(500); };
  const pick = async (id, text) => {
    for (let attempt = 1; attempt <= 6; attempt++) {
      select(id);
      await sleep(1500);
      for (let i = 0; i < 14; i++) {
        if (clickItem(text)) return true;
        await sleep(150);
      }
    }
    return false;
  };
  const menuItems = () => [...document.querySelectorAll("[class*=_label_]")].filter(vis).map((e) => e.textContent);
  const waitFor = async (check, ms) => {
    const end = Date.now() + ms;
    while (Date.now() < end) {
      let value = null;
      try { value = await check(); } catch { value = null; }
      if (value) return value;
      await sleep(250);
    }
    return null;
  };
  const price = () => (document.body.innerText.match(/Total List Price\s*\$[\d,]+(\.\d+)?/) || [""])[0].replace(/\s+/g, " ");
  const skuRequests = (needle = "") => performance.getEntriesByType("resource").map((e) => e.name).filter((n) => n.includes("pricing-v2/resolve") && decodeURIComponent(n).includes(needle)).map((n) => decodeURIComponent(n).split("?")[1]?.slice(0, 500));
  const accordion = () => [...document.querySelectorAll("button[aria-expanded]")].filter(vis).map((b) => ({ t: txt(b.innerText).slice(0, 40), open: b.getAttribute("aria-expanded") }));
  const openSection = async (title) => {
    const trig = [...document.querySelectorAll("button[aria-expanded]")].find((b) => txt(b.innerText) === title);
    if (!trig) return false;
    if (trig.getAttribute("aria-expanded") !== "true") { trig.scrollIntoView({ block: "center" }); trig.click(); await sleep(900); }
    return true;
  };
  const sectionPanel = (title) => {
    const trig = [...document.querySelectorAll("button[aria-expanded]")].find((b) => txt(b.innerText) === title);
    return trig ? document.getElementById(trig.getAttribute("aria-controls") || "") : null;
  };
  const swatches = (panel) => [...(panel?.querySelectorAll("[aria-label]") ?? [])].filter((b) => b.tagName === "BUTTON" && /selectButton/.test(b.className)).map((b) => txt(b.getAttribute("aria-label")));
  const filterButtons = (panel) => [...(panel?.querySelectorAll("button[aria-haspopup=listbox]") ?? [])].map((b) => txt(b.innerText));
  const nextStep = async () => {
    const all = [...document.querySelectorAll("button,a")].filter((e) => vis(e) && txt(e.innerText).startsWith("Next:"));
    if (!all.length) return false;
    all[0].click();
    await sleep(3000);
    return txt(all[0].innerText);
  };
  const dismissWalkthrough = async () => {
    for (const t of ["Get Started", "Skip"]) {
      const b = button(t);
      if (b) { b.click(); await sleep(600); return t; }
    }
    return null;
  };

  const ids = () => {
    const comp = api()?.config?.compositionManager?.getActiveComposition?.();
    const map = comp?.getOrderProductIds?.();
    return map ? Object.keys(map).sort((a, b) => (map[a] ?? 0) - (map[b] ?? 0)) : [];
  };
  const configs = async () => {
    const out = [];
    for (const id of ids()) {
      const c = await api().getConfig(id);
      out.push({ id: id.replace(/-[a-z0-9]{6,}$/i, ""), Width: c?.Width, Drawers: c?.Drawers, HandleStyle: c?.HandleStyle, Handle: c?.Handle, HandleColor: c?.HandleColor, CabinetColor: c?.CabinetColor, LegColor: c?.LegColor, sinkType: c?.sinkType });
    }
    return out;
  };
  const tap = (el, w = win()) => {
    const r = el.getBoundingClientRect();
    const init = { bubbles: true, cancelable: true, composed: true, view: w, clientX: r.left + r.width / 2, clientY: r.top + r.height / 2, button: 0 };
    for (const [type, Ctor] of [["pointerdown", w.PointerEvent], ["mousedown", w.MouseEvent], ["pointerup", w.PointerEvent], ["mouseup", w.MouseEvent], ["click", w.MouseEvent]]) {
      el.dispatchEvent(new Ctor(type, { ...init, buttons: type.endsWith("down") ? 1 : 0, ...(Ctor === w.PointerEvent ? { pointerId: 1, pointerType: "mouse", isPrimary: true } : {}) }));
    }
  };
  const pluses = () => [...(win()?.document.querySelectorAll(".ap-plus-btn") ?? [])].filter((b) => b.style.display !== "none" && vis(b));
  const byLabel = (t) => [...document.querySelectorAll("button")].find((x) => x.getAttribute("aria-label") === t || txt(x.innerText) === t);
  const sidebar = () => document.querySelector("[class*=cabinetStyleSidebar]");
  const sidebarSelect = (labelText) => {
    const side = sidebar();
    return side ? [...side.querySelectorAll("div")].find((d) => d.firstElementChild && txt(d.firstElementChild.textContent) === labelText && d.querySelector("button"))?.querySelector("button") : null;
  };
  const chooseInSidebar = async (labelText, value) => {
    const b = sidebarSelect(labelText);
    if (!b) return { err: "no select " + labelText };
    b.click();
    await sleep(600);
    const lb = [...document.querySelectorAll(`[role=listbox][aria-label="${labelText}"]`)].pop();
    if (!lb) return { err: "no listbox " + labelText };
    const offered = [...lb.querySelectorAll("[role=option]")].map((o) => txt(o.innerText));
    const opt = [...lb.querySelectorAll("[role=option]")].find((o) => txt(o.innerText) === value);
    if (!opt) { b.click(); return { err: "no option " + value, offered }; }
    (opt.querySelector("button") || opt).click();
    await sleep(900);
    return { offered, chose: value };
  };
  const skus = (needle = "VAN-") => [...new Set((window.__skus ?? []).filter((s) => s.includes(needle)))];
  const skusSince = (mark, needle = "VAN-") => [...new Set((window.__skus ?? []).slice(mark).filter((s) => s.includes(needle)))];
  const skuMark = () => (window.__skus ?? []).length;
  const fieldRead = async (title) => {
    const opened = await openSection(title);
    const panel = sectionPanel(title);
    if (!panel) return { err: "no panel " + title, opened };
    const swatchButtons = [...panel.querySelectorAll("button[class*=selectButton]")];
    const selected = swatchButtons.filter((b) => /active|selected/i.test(b.className) || b.getAttribute("aria-pressed") === "true" || b.getAttribute("aria-checked") === "true" || /active|selected/i.test(b.parentElement?.className ?? "")).map((b) => txt(b.getAttribute("aria-label")));
    const groups = [...panel.querySelectorAll("section")].map((sec) => ({ group: txt(sec.firstElementChild?.textContent), n: sec.querySelectorAll("button[class*=selectButton]").length }));
    return { swatches: swatchButtons.map((b) => txt(b.getAttribute("aria-label"))), selected, groups, filters: filterButtons(panel) };
  };
  const filterOptions = async (title, filter) => {
    const panel = sectionPanel(title);
    const b = [...panel.querySelectorAll("button[aria-haspopup=listbox]")].find((x) => txt(x.innerText).startsWith(filter));
    if (!b) return { err: "no filter " + filter };
    b.click();
    await sleep(500);
    const lb = [...document.querySelectorAll(`[role=listbox][aria-label="${filter}"]`)].pop();
    const out = lb ? [...lb.querySelectorAll("[role=option]")].map((o) => txt(o.querySelector("span")?.innerText || o.innerText)) : null;
    b.click();
    await sleep(300);
    return out;
  };
  const chooseFilter = async (title, filter, value) => {
    const panel = sectionPanel(title);
    const b = [...panel.querySelectorAll("button[aria-haspopup=listbox]")].find((x) => txt(x.innerText).startsWith(filter));
    if (!b) return { err: "no filter " + filter };
    b.click();
    await sleep(500);
    const lb = [...document.querySelectorAll(`[role=listbox][aria-label="${filter}"]`)].pop();
    const opt = lb && [...lb.querySelectorAll("[role=option]")].find((o) => txt(o.querySelector("span")?.innerText || o.innerText) === value);
    if (!opt) return { err: "no value " + value };
    (opt.querySelector("button") || opt).click();
    await sleep(800);
    return { chose: value, label: txt(b.innerText) };
  };
  const pickSwatch = async (title, name) => {
    await openSection(title);
    const panel = sectionPanel(title);
    const b = panel && [...panel.querySelectorAll("button[class*=selectButton]")].find((x) => txt(x.getAttribute("aria-label")) === name);
    if (!b) return false;
    b.scrollIntoView({ block: "center" });
    b.click();
    await sleep(2500);
    return true;
  };
  const undoBtn = () => document.querySelector('[data-tooltip="Image"]')?.nextElementSibling;
  const redoBtn = () => undoBtn()?.nextElementSibling;
  const popup = () => {
    const titles = ["Update Handle Style?", "Handle Change Blocked", "Update Design?", "Sink", "Remove Side Shelf?"];
    const t = titles.find((x) => [...document.querySelectorAll("div,h2,h3")].some((e) => vis(e) && txt(e.textContent) === x));
    if (!t) return null;
    const el = [...document.querySelectorAll("div,h2,h3")].find((e) => vis(e) && txt(e.textContent) === t);
    const box = el.closest("[class*=confirmPopup],[role=alertdialog],[role=dialog]") ?? el.parentElement?.parentElement;
    return { title: t, text: txt(box?.innerText).slice(0, 300), buttons: [...(box?.querySelectorAll("button") ?? [])].filter(vis).map((b) => txt(b.innerText)) };
  };
  const clickInPopup = async (label) => {
    const b = [...document.querySelectorAll("button")].filter(vis).reverse().find((x) => txt(x.innerText) === label);
    if (!b) return false;
    b.click();
    await sleep(2500);
    return true;
  };
  const menuPath = async (id, labels) => {
    for (let attempt = 1; attempt <= 6; attempt++) {
      select(id);
      await sleep(1500);
      let ok = true;
      for (const t of labels) {
        let done = false;
        for (let i = 0; i < 14 && !done; i++) {
          const item = label(t)?.closest("[class*=_item_]");
          if (item) {
            item.dispatchEvent(new MouseEvent("mouseover", { bubbles: true }));
            item.dispatchEvent(new MouseEvent("mouseenter", { bubbles: true }));
            item.click();
            done = true;
          } else {
            await sleep(150);
          }
        }
        if (!done) { ok = false; break; }
        await sleep(350);
      }
      if (ok) return true;
    }
    return false;
  };
  const rawIds = () => ids();


  const swatchState = (title, name) => {
    const panel = sectionPanel(title);
    const b = panel && [...panel.querySelectorAll("button[class*=selectButton]")].find((x) => txt(x.getAttribute("aria-label")) === name);
    if (!b) return { present: false };
    const wrap = b.closest("[class*=item],[class*=option],[class*=card]") ?? b.parentElement;
    return { present: true, disabled: b.disabled === true || b.getAttribute("aria-disabled") === "true", cls: String(b.className).replace(/_[a-z0-9]{6}_?\d*/gi, "").slice(0, 80), wrapCls: String(wrap?.className ?? "").replace(/_[a-z0-9]{6}_?\d*/gi, "").slice(0, 80), title: b.getAttribute("title") ?? wrap?.getAttribute("title") ?? null, tip: wrap?.getAttribute("data-tooltip") ?? b.getAttribute("data-tooltip") ?? null, text: txt(wrap?.parentElement?.innerText).slice(0, 120) };
  };
  const sections = () => [...document.querySelectorAll("button[aria-expanded]")].filter((b) => vis(b) && txt(b.innerText)).map((b) => txt(b.innerText));
  const stepTo = async (name) => {
    const a = [...document.querySelectorAll("nav a")].find((x) => txt(x.innerText) === name);
    if (!a) return false;
    a.click();
    await sleep(2500);
    return true;
  };
  const placeCabinet = async ({ type, style, width, side = "right", expected }) => {
    await openSection("Cabinet Type");
    byLabel(type)?.click();
    await sleep(1400);
    byLabel(style)?.click();
    await sleep(1400);
    const w = width ? await chooseInSidebar("Width", width) : null;
    await sleep(500);
    const list = pluses().sort((a, b) => a.getBoundingClientRect().left - b.getBoundingClientRect().left);
    if (!list.length) return { err: "no plus", w, sideText: txt(sidebar()?.innerText).slice(0, 200) };
    const before = ids().length;
    tap(side === "right" ? list.at(-1) : list[0]);
    await waitFor(async () => ids().length === before + 1, 25000);
    await sleep(2500);
    return { w, placed: ids().length === (expected ?? before + 1) };
  };
  const closeStyleSidebar = async () => { sidebar()?.firstElementChild?.click(); await sleep(500); await deselect(); };


  const hoverReason = async (title, name) => {
    await openSection(title);
    const panel = sectionPanel(title);
    const b = panel && [...panel.querySelectorAll("button[class*=selectButton]")].find((x) => txt(x.getAttribute("aria-label")) === name);
    if (!b) return null;
    b.scrollIntoView({ block: "center" });
    await sleep(200);
    const targets = [b, b.parentElement, b.parentElement?.parentElement].filter(Boolean);
    for (const t of targets) {
      for (const type of ["pointerover", "pointerenter", "mouseover", "mouseenter", "mousemove", "focusin"]) t.dispatchEvent(new MouseEvent(type, { bubbles: type !== "mouseenter" && type !== "pointerenter", cancelable: true, view: window }));
    }
    await sleep(900);
    const shown = [...document.querySelectorAll("[role=tooltip],[class*=ooltip],[class*=hint],[class*=Hint]")].filter(vis).map((e) => txt(e.innerText)).filter(Boolean);
    const around = txt(b.closest("[class*=sGrid],[class*=item]")?.innerText).slice(0, 200);
    for (const t of targets) for (const type of ["pointerout", "pointerleave", "mouseout", "mouseleave", "focusout"]) t.dispatchEvent(new MouseEvent(type, { bubbles: type !== "mouseleave" && type !== "pointerleave", cancelable: true, view: window }));
    return { shown, around };
  };


  // Reads the hint of a refused tile: the Hint opens on the mouse entering the tile's wrapper.
  const reasonOf = async (title, name) => {
    await openSection(title);
    const panel = sectionPanel(title);
    const b = [...(panel?.querySelectorAll("button[aria-label]") ?? [])].find((x) => txt(x.getAttribute("aria-label")) === name);
    if (!b) return { present: false };
    const refused = b.disabled === true || b.getAttribute("aria-disabled") === "true";
    if (!refused) return { present: true, refused };
    b.scrollIntoView({ block: "center" });
    await sleep(150);
    const host = b.closest("div");
    for (const type of ["pointerover", "mouseover", "mouseenter", "mousemove"]) host.dispatchEvent(new MouseEvent(type, { bubbles: type !== "mouseenter", cancelable: true, view: window }));
    await sleep(350);
    const texts = [...document.querySelectorAll("*")].filter((e) => e.children.length === 0 && vis(e) && /(not available|Not available|Maximum)/.test(txt(e.textContent))).map((e) => txt(e.textContent));
    for (const type of ["pointerout", "mouseout", "mouseleave"]) host.dispatchEvent(new MouseEvent(type, { bubbles: type !== "mouseleave", cancelable: true, view: window }));
    await sleep(100);
    return { present: true, refused, hint: [...new Set(texts)] };
  };
  const refusedTiles = (title) => [...(sectionPanel(title)?.querySelectorAll("button[aria-label][aria-disabled=true]") ?? [])].map((b) => txt(b.getAttribute("aria-label")));
  const placeWithDepth = async ({ type, style, width, depth }) => {
    await openSection("Cabinet Type");
    byLabel(type)?.click();
    await sleep(1400);
    byLabel(style)?.click();
    await sleep(1400);
    const w = width ? await chooseInSidebar("Width", width) : null;
    const d = depth ? await chooseInSidebar("Depth", depth) : null;
    await sleep(500);
    const list = pluses().sort((a, b) => a.getBoundingClientRect().left - b.getBoundingClientRect().left);
    if (!list.length) return { err: "no plus", w, d };
    const before = ids().length;
    tap(list.at(-1));
    await waitFor(async () => ids().length === before + 1, 25000);
    await sleep(2500);
    return { w, d, placed: ids().length === before + 1 };
  };
  const filterRows = async (title) => {
    await openSection(title);
    const panel = sectionPanel(title);
    const b = [...panel.querySelectorAll("button[aria-haspopup=listbox]")].find((x) => txt(x.innerText).startsWith("Material"));
    if (!b) return null;
    b.click();
    await sleep(500);
    const lb = [...document.querySelectorAll("[role=listbox][aria-label=Material]")].pop();
    const rows = [];
    for (const o of lb?.querySelectorAll("[role=option]") ?? []) {
      const off = o.getAttribute("aria-disabled") === "true";
      if (!off) { rows.push({ t: txt(o.innerText) }); continue; }
      for (const type of ["pointerover", "mouseover", "mouseenter", "mousemove"]) o.dispatchEvent(new MouseEvent(type, { bubbles: type !== "mouseenter", cancelable: true, view: window }));
      const host = o.parentElement;
      for (const type of ["pointerover", "mouseover", "mouseenter", "mousemove"]) host?.dispatchEvent(new MouseEvent(type, { bubbles: type !== "mouseenter", cancelable: true, view: window }));
      await sleep(350);
      const texts = [...document.querySelectorAll("*")].filter((e) => e.children.length === 0 && vis(e) && /(Not available)/.test(txt(e.textContent))).map((e) => txt(e.textContent));
      rows.push({ t: txt(o.innerText), off, hint: [...new Set(texts)] });
      for (const type of ["pointerout", "mouseout", "mouseleave"]) { o.dispatchEvent(new MouseEvent(type, { bubbles: type !== "mouseleave", cancelable: true, view: window })); host?.dispatchEvent(new MouseEvent(type, { bubbles: type !== "mouseleave", cancelable: true, view: window })); }
      await sleep(80);
    }
    b.click();
    await sleep(300);
    return rows;
  };

  window.__q = { sleep, frameEl, win, api, txt, vis, scope, cabinets, brief, button, clickText, label, clickItem, select, deselect, pick, menuItems, waitFor, price, skuRequests, accordion, openSection, sectionPanel, swatches, filterButtons, nextStep, dismissWalkthrough, ids, rawIds, configs, tap, pluses, byLabel, sidebar, sidebarSelect, chooseInSidebar, skus, skusSince, skuMark, fieldRead, filterOptions, chooseFilter, pickSwatch, undoBtn, redoBtn, popup, clickInPopup, menuPath, swatchState, sections, stepTo, placeCabinet, closeStyleSidebar, hoverReason, reasonOf, refusedTiles, placeWithDepth, filterRows };
  await waitFor(async () => Boolean(api()?.cabinets), 45000);
  await sleep(2500);
  const w = await dismissWalkthrough();
  return { walkthrough: w, url: location.pathname + location.search, configs: await configs().catch((e) => String(e)), price: price() };
}

async () => {
    const q = window.__q;
